/**
 * @file
 * @brief       All the emlearn code of the Sound Spotter: the FFT, and the
 *              random forest of model.h generated by tools/train.py
 *
 * The emlearn headers define non static functions, so they are included in
 * this file only. tools/train.py builds it without SOUND_HAVE_MODEL to
 * compute the features before there is a model.
 */

#include "sound.h"

#pragma GCC diagnostic push
#pragma GCC diagnostic ignored "-Wunused-function"
#pragma GCC diagnostic ignored "-Wunused-parameter"
#include "eml_fft.h"
#ifdef SOUND_HAVE_MODEL
/* the training tools build the C model with the model they just made */
#ifndef MODEL_HEADER
#define MODEL_HEADER "model.h"
#endif
#include MODEL_HEADER
#endif
#pragma GCC diagnostic pop

static float _fft_sin[SOUND_FRAME / 2];
static float _fft_cos[SOUND_FRAME / 2];
static EmlFFT _fft = { SOUND_FRAME / 2, _fft_sin, _fft_cos };

void sound_fft_init(void)
{
    eml_fft_fill(_fft, SOUND_FRAME);
}

void sound_fft(float *re, float *im)
{
    eml_fft_forward(_fft, re, im, SOUND_FRAME);
}

#ifdef SOUND_HAVE_MODEL
int sound_classify(const int16_t *features, float *proba)
{
    if (eml_trees_predict_proba(&sound_model, features, SOUND_FEATURES,
                                proba, SOUND_CLASSES) != EmlOk) {
        return -1;
    }
    int best = 0;
    for (int i = 1; i < SOUND_CLASSES; i++) {
        if (proba[i] > proba[best]) {
            best = i;
        }
    }
    return best;
}
#endif
